import { APP_VERSION, DEMO_NOW, createDemoData, cloneData, priorityRank, addHours, dayISO } from './data.js';
import { loadState, saveState, clearState } from './storage.js';
import { scheduleAll, manualMove, applyPriority, computePlanningMetrics, validateBooking } from './planner.js';
import { kpis, calibrationStatus, calibrationAt, nextScheduledCalibration, resourceUtilisation, categoryMetrics, bottlenecks, skillsRisks, runDiagnostics, recomputeRequirementStatuses, periodMetrics, periodTrend, issueAnalytics } from './diagnostics.js';

let state=null, route='dashboard', lastPlanDiagnostics=null;
const main=document.getElementById('main'), nav=document.getElementById('nav'), modal=document.getElementById('modal'), modalBody=document.getElementById('modalBody'), searchOverlay=document.getElementById('searchOverlay');
const fmtDate=(x,withTime=false)=>x?new Date(x).toLocaleString(undefined,withTime?{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}:{year:'numeric',month:'short',day:'numeric'}):'—';
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const statusTone=s=>/Verified|Approved|Released|Closed|Completed|Available|Valid|Pass|On Track|Ready/.test(s)?'green':/Failed|Expired|Breakdown|Overdue|Late/.test(s)?'red':/Blocked|At Risk|Due|Maintenance|Awaiting|Rework/.test(s)?'amber':/Planned|In Progress|Reserved|High/.test(s)?'blue':'grey';
const pill=s=>`<span class="pill ${statusTone(String(s))}">${esc(s)}</span>`;
const pct=(n,d)=>Math.round((n/Math.max(1,d))*100);

function addCompletedBookings(data){if(data.bookings?.some(b=>b.status==='Completed'))return;for(const l of data.legs.filter(x=>x.status==='Completed'&&x.actualStart&&x.actualEnd)){data.bookings.push({id:`BKG-${l.id}`,legId:l.id,programmeId:l.programmeId,methodId:l.methodId,start:l.actualStart,end:l.actualEnd,staffEnd:l.actualEnd,equipmentId:l.equipmentId,staffId:l.staffId,locked:true,status:'Completed',priority:data.programmes.find(p=>p.id===l.programmeId)?.priority||'Normal',dueDate:l.dueDate,lateHours:0});}}
async function init(){document.getElementById('versionText').textContent=`v${APP_VERSION}`;let loaded=await loadState();state=ensureStateShape(loaded?.meta?.version===APP_VERSION?loaded:createDemoData());addCompletedBookings(state);recomputeRequirementStatuses(state);if(!state.settings.lastPlannerRun){const r=scheduleAll(state,{recordAudit:false});state=r.data;lastPlanDiagnostics=r.diagnostics;}await saveState(state);bindGlobal();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./service-worker.js').catch(()=>{});}
function bindGlobal(){nav.addEventListener('click',e=>{const b=e.target.closest('[data-route]');if(b)go(b.dataset.route)});document.querySelector('.brand').addEventListener('click',()=>go('dashboard'));document.getElementById('mobileNavBtn').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));document.getElementById('modalClose').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.getElementById('roleSelect').value=state.settings.role||'Lab Manager';document.getElementById('roleSelect').onchange=async e=>{state.settings.role=e.target.value;state.audit.push(audit('Role view changed','Demo UI','',e.target.value));await persist();const defaults={Technician:'execution','Test Engineer':'programmes',Planner:'planning','Lab Manager':'dashboard',Quality:'requirements'};go(defaults[e.target.value]||'dashboard');};const s=document.getElementById('globalSearch');s.oninput=()=>search(s.value);s.onkeydown=e=>{if(e.key==='Escape'){s.value='';searchOverlay.classList.add('hidden')}};document.getElementById('importFile').onchange=importJSON;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});}
function go(r){route=r;document.getElementById('sidebar').classList.remove('open');for(const b of nav.querySelectorAll('button'))b.classList.toggle('active',b.dataset.route===r);render();window.scrollTo({top:0});}
async function persist(){await saveState(state);}
function audit(action,entity,prev,next){return{timestamp:new Date().toISOString(),actor:state.settings.actor||'Demo Lab Manager',action,entity,previousValue:String(prev??''),newValue:String(next??'')}}
function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.classList.remove('hidden');clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.add('hidden'),3200)}
function openModal(html){modalBody.innerHTML=html;modal.classList.remove('hidden');modalBody.querySelector('input,select,button')?.focus();}
function closeModal(){modal.classList.add('hidden');modalBody.innerHTML=''}
function pageHead(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`}
function kpiCard(label,value,sub=''){return `<div class="card kpi-card"><div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub}</div></div>`}
function section(title,body,hint=''){return `<section class="card"><div class="section-title"><h2>${title}</h2>${hint?`<span class="hint">${hint}</span>`:''}</div>${body}</section>`}

function ensureStateShape(x){x.testRuns=x.testRuns||[];x.issues=x.issues||[];x.disruptions=x.disruptions||[];x.specifications=x.specifications||[];x.documents=x.documents||[];x.settings=x.settings||{};x.settings.kpiPeriod=x.settings.kpiPeriod||{preset:'30d',start:dayISO(-30,0).slice(0,10),end:dayISO(0,23).slice(0,10)};x.settings.scenarioFocusProgramme=x.settings.scenarioFocusProgramme||x.programmes?.[0]?.id||'';return x}
function periodRange(){const p=state.settings.kpiPeriod||{};return {start:p.start||dayISO(-30,0).slice(0,10),end:p.end||dayISO(0,23).slice(0,10),preset:p.preset||'custom'}}
function periodLabel(){const p=periodRange();return `${fmtDate(p.start)} – ${fmtDate(p.end)}`}
function isoDate(d){return new Date(d).toISOString().slice(0,10)}
function presetRange(v){const now=new Date(DEMO_NOW),d=new Date(DEMO_NOW);d.setUTCHours(0,0,0,0);if(v==='7d')return{start:isoDate(new Date(d.getTime()-6*86400000)),end:isoDate(d)};if(v==='30d')return{start:isoDate(new Date(d.getTime()-29*86400000)),end:isoDate(d)};if(v==='90d')return{start:isoDate(new Date(d.getTime()-89*86400000)),end:isoDate(d)};const mon=(x)=>{const z=new Date(x);const shift=(z.getUTCDay()+6)%7;z.setUTCDate(z.getUTCDate()-shift);return z};if(v==='thisWeek'){const a=mon(d);return{start:isoDate(a),end:isoDate(new Date(a.getTime()+6*86400000))}}if(v==='lastWeek'){const a=new Date(mon(d).getTime()-7*86400000);return{start:isoDate(a),end:isoDate(new Date(a.getTime()+6*86400000))}}if(v==='thisMonth'){return{start:`${now.getUTCFullYear()}-${String(now.getUTCMonth()+1).padStart(2,'0')}-01`,end:isoDate(new Date(Date.UTC(now.getUTCFullYear(),now.getUTCMonth()+1,0)))}}if(v==='lastMonth'){const y=now.getUTCMonth()===0?now.getUTCFullYear()-1:now.getUTCFullYear(),m=now.getUTCMonth()===0?11:now.getUTCMonth()-1;return{start:`${y}-${String(m+1).padStart(2,'0')}-01`,end:isoDate(new Date(Date.UTC(y,m+1,0)))}}return periodRange()}
function weekValueFor(date){const d=new Date(Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),date.getUTCDate()));d.setUTCDate(d.getUTCDate()+4-(d.getUTCDay()||7));const y=new Date(Date.UTC(d.getUTCFullYear(),0,1));const w=Math.ceil((((d-y)/86400000)+1)/7);return `${d.getUTCFullYear()}-W${String(w).padStart(2,'0')}`}
function periodControls(){const p=periodRange(),now=new Date(DEMO_NOW);return `<div class="period-bar card"><div class="period-title"><strong>KPI period</strong><span>${periodLabel()}</span></div><label>Preset<select id="periodPreset"><option value="custom" ${p.preset==='custom'?'selected':''}>Custom</option>${[['thisWeek','This week'],['lastWeek','Last week'],['thisMonth','This month'],['lastMonth','Last month'],['7d','Last 7 days'],['30d','Last 30 days'],['90d','Last 90 days']].map(([v,l])=>`<option value="${v}" ${p.preset===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Week<input id="periodWeek" type="week" value="${weekValueFor(now)}"></label><label>Month<input id="periodMonth" type="month" value="${now.getUTCFullYear()}-${String(now.getUTCMonth()+1).padStart(2,'0')}"></label><label>From<input id="periodStart" type="date" value="${p.start}"></label><label>To<input id="periodEnd" type="date" value="${p.end}"></label></div>`}
async function wirePeriodControls(){const preset=document.getElementById('periodPreset'),week=document.getElementById('periodWeek'),month=document.getElementById('periodMonth'),start=document.getElementById('periodStart'),end=document.getElementById('periodEnd');if(!preset)return;const set=async(p)=>{state.settings.kpiPeriod=p;await persist();render()};preset.onchange=()=>{const r=presetRange(preset.value);set({...r,preset:preset.value})};week.onchange=()=>{const m=/^(\d{4})-W(\d{2})$/.exec(week.value);if(!m)return;const y=+m[1],w=+m[2],jan4=new Date(Date.UTC(y,0,4)),mon=new Date(jan4.getTime()-((jan4.getUTCDay()+6)%7)*86400000+(w-1)*7*86400000);set({preset:'custom',start:isoDate(mon),end:isoDate(new Date(mon.getTime()+6*86400000))})};month.onchange=()=>{const [y,m]=month.value.split('-').map(Number);if(!y||!m)return;set({preset:'custom',start:`${y}-${String(m).padStart(2,'0')}-01`,end:isoDate(new Date(Date.UTC(y,m,0)))})};for(const el of [start,end])el.onchange=()=>{if(!start.value||!end.value)return;if(new Date(end.value)<new Date(start.value)){toast('KPI period end must be on or after the start date.');return}set({preset:'custom',start:start.value,end:end.value})}}
function trendViz(tr){const rows=tr.rows||[];if(!rows.length)return'<div class="empty">No period data.</div>';const W=680,H=230,pad=34,max=Math.max(1,...rows.flatMap(r=>[r.completed,r.issues]));const pts=(key)=>rows.map((r,i)=>`${pad+(rows.length===1?0:i*(W-pad*2)/(rows.length-1))},${H-pad-(r[key]/max)*(H-pad*2)}`).join(' ');const labels=rows.filter((_,i)=>i===0||i===rows.length-1||i===Math.floor(rows.length/2)).map((r)=>{const i=rows.indexOf(r),x=pad+(rows.length===1?0:i*(W-pad*2)/(rows.length-1));return`<text x="${x}" y="${H-9}" text-anchor="middle">${new Date(r.date).toLocaleDateString(undefined,{month:'short',day:'numeric'})}</text>`}).join('');return `<div class="chart-legend"><span><i class="legend-dot teal"></i>Tests completed</span><span><i class="legend-dot amber"></i>Issues</span><span>${tr.mode} buckets</span></div><svg class="chart-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Tests completed and issues over selected period"><line x1="${pad}" y1="${H-pad}" x2="${W-pad}" y2="${H-pad}" class="axis"/><polyline points="${pts('completed')}" class="line teal"/><polyline points="${pts('issues')}" class="line amber"/>${rows.map((r,i)=>{const x=pad+(rows.length===1?0:i*(W-pad*2)/(rows.length-1)),y1=H-pad-(r.completed/max)*(H-pad*2),y2=H-pad-(r.issues/max)*(H-pad*2);return`<circle cx="${x}" cy="${y1}" r="3.5" class="point teal"><title>${r.date}: ${r.completed} tests completed</title></circle><circle cx="${x}" cy="${y2}" r="3.5" class="point amber"><title>${r.date}: ${r.issues} issues</title></circle>`}).join('')}${labels}</svg>`}
function horizontalViz(items,valueKey='count',suffix=''){if(!items?.length)return'<div class="empty">No data in this period.</div>';const max=Math.max(1,...items.map(x=>Number(x[valueKey])||0));return `<div class="viz-bars">${items.map((x,i)=>`<div class="viz-bar"><div><strong>${esc(x.name||x.label||x.category)}</strong><span>${Number(x[valueKey])||0}${suffix}${x.delayHours!=null?` · ${Math.round(x.delayHours)}h delay`:''}</span></div><div class="viz-track"><i style="width:${Math.max(2,(Number(x[valueKey])||0)/max*100)}%"></i></div></div>`).join('')}</div>`}
function rootCauseDonut(rows){if(!rows?.length)return'<div class="empty">No issues in this period.</div>';const total=rows.reduce((a,x)=>a+x.count,0),palette=['#0f897f','#bd7c13','#b63b45','#3268b8','#7651a8','#61777c'];let cur=0;const seg=rows.slice(0,6).map((x,i)=>{const a=cur,b=cur+x.count/total*100;cur=b;return`${palette[i]} ${a}% ${b}%`}).join(',');return `<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${seg})"><div><strong>${total}</strong><span>issues</span></div></div><div class="donut-legend">${rows.slice(0,6).map((x,i)=>`<div><i style="background:${palette[i]}"></i><span>${esc(x.name)}</span><strong>${x.count} · ${Math.round(x.count/total*100)}%</strong></div>`).join('')}</div></div>`}
function outcomeViz(pm){const total=Math.max(1,pm.completed),pass=pm.pass/total*100,fail=pm.failed/total*100,rework=pm.rework/total*100;return `<div class="outcome-stack"><div class="outcome-bar"><span class="pass" style="width:${pass}%"></span><span class="rework" style="width:${rework}%"></span><span class="fail" style="width:${fail}%"></span></div><div class="chart-legend"><span>PASS ${pm.pass} (${Math.round(pass)}%)</span><span>REWORK ${pm.rework} (${Math.round(rework)}%)</span><span>FAIL ${pm.failed} (${Math.round(fail)}%)</span></div></div>`}
function priorityMaps(){const ps=state.programmes,focus=state.settings.scenarioFocusProgramme||ps[0]?.id;const due={};for(const p of ps){const d=(new Date(p.dueDate)-DEMO_NOW)/86400000;due[p.id]=d<=21?'Critical':d<=35?'High':d<=50?'Normal':'Low'}const sorted=[...ps].sort((a,b)=>b.businessPriority-a.businessPriority),biz={};sorted.forEach((p,i)=>biz[p.id]=i<2?'Critical':i<5?'High':i<8?'Normal':'Low');const foc={};for(const p of ps)foc[p.id]=p.id===focus?'Critical':p.priority==='Critical'?'High':p.priority==='High'?'Normal':'Low';return[{id:'baseline',name:'Baseline priorities',map:null,desc:'Current project priorities'},{id:'due',name:'Due-date protection',map:due,desc:'Near-term due dates receive highest priority'},{id:'business',name:'Business-value first',map:biz,desc:'Highest business-priority scores receive capacity first'},{id:'focus',name:`Focus ${focus}`,map:foc,desc:'Selected project becomes Critical; other work yields capacity'}]}
function scenarioComparison(){return priorityMaps().map(sc=>{const scenario=sc.map?{type:'priority_mix',priorityMap:sc.map,label:sc.name}:null;const r=scheduleAll(state,{scenario,recordAudit:false}),d=r.data,late=d.bookings.filter(b=>b.lateHours>0),atRisk=d.programmes.filter(p=>['Late','At Risk','Blocked'].includes(p.scheduleRisk)).length,onTime=d.programmes.filter(p=>p.forecastCompletion&&new Date(p.forecastCompletion)<=new Date(p.dueDate)).length,totalLate=Math.round(late.reduce((a,b)=>a+b.lateHours,0)/24*10)/10;return{...sc,atRisk,onTime,late:late.length,totalLate,moved:r.diagnostics.moved.length,unscheduled:r.diagnostics.unscheduled.length}})}
function scenarioCards(){const rows=scenarioComparison(),max=Math.max(1,...rows.map(x=>x.totalLate));return `<div class="scenario-grid">${rows.map(x=>`<article class="scenario-card ${state.settings.scenario?.label===x.name?'active':''}"><div class="scenario-top"><div><strong>${esc(x.name)}</strong><small>${esc(x.desc)}</small></div>${x.id!=='baseline'?`<button class="btn small" data-act="apply-priority-scenario" data-strategy="${x.id}">Apply</button>`:''}</div><div class="scenario-numbers"><span><b>${x.onTime}</b> on time</span><span><b>${x.atRisk}</b> at risk</span><span><b>${x.totalLate}</b> late days</span></div><div class="viz-track"><i style="width:${Math.max(2,x.totalLate/max*100)}%"></i></div><small>${x.moved} bookings move · ${x.unscheduled} unscheduled</small></article>`).join('')}</div>`}

function render(){recomputeRequirementStatuses(state);const views={dashboard:renderDashboard,requirements:renderRequirements,specifications:renderSpecifications,programmes:renderProgrammes,planning:renderPlanning,execution:renderExecution,duts:renderDUTs,library:renderLibrary,equipment:renderEquipment,calibration:renderCalibration,people:renderPeople,analytics:renderAnalytics,admin:renderAdmin};main.innerHTML=(views[route]||renderDashboard)();wireRoute();}

function renderDashboard(){const vd=filteredDashboardData(),K=kpis(vd),p=periodRange(),PM=periodMetrics(vd,p.start,p.end),TR=periodTrend(vd,p.start,p.end),IA=issueAnalytics(vd,p.start,p.end),bn=bottlenecks(vd),cats=categoryMetrics(vd).slice(0,7),role=state.settings.role||'Lab Manager';
 return pageHead('Laboratory Operations Dashboard',`Management KPIs, delivery, quality and constraints · ${role} view`,`<button class="btn" data-act="report-issue">＋ Log Delay / Issue</button><button class="btn primary" data-act="update-plan">↻ Update Plan Now</button>`)+periodControls()+dashboardFilterBar()+
 `<div class="grid kpi visual-kpis">${kpiCard('Tests completed',PM.completed,periodLabel())}${kpiCard('On-time completion',`${PM.onTimePct}%`,`${PM.completed-PM.failed} non-failed executions`)}${kpiCard('Pass rate',`${PM.passRate}%`,`${PM.pass} pass · ${PM.rework} rework · ${PM.failed} fail`)}${kpiCard('Issues raised',PM.issues,`${PM.issueDelayHours}h recorded delay impact`)}${kpiCard('Equipment utilisation',`${PM.equipmentUtil}%`,'Selected KPI period')}${kpiCard('Staff utilisation',`${PM.staffUtil}%`,'Selected KPI period')}</div>`+
 `<div class="grid kpi compact-kpis">${kpiCard('Active programmes',K.activeProgrammes,`${K.atRisk} at risk / blocked`)}${kpiCard('Open tests',K.testsOpen,`${K.inProgress} in progress · ${K.overdue} forecast late`)}${kpiCard('Requirements verified',`${K.reqVerified}%`,`${K.reqCoverage}% covered · ${K.reqFailed} failed`)}${kpiCard('Bad-spec issues',PM.specIssues,`${PM.specIssuePct}% of period issues`)}${kpiCard('Execution issues',PM.execIssues,`${PM.execIssuePct}% of period issues`)}${kpiCard('Development queue',K.devQueue,`${K.devHours}h open workload`)}</div>`+
 `<div class="grid section-grid equal">${section('Performance trend',trendViz(TR),`Selected period · ${TR.mode} buckets`)}${section('Outcome & root-cause mix',outcomeViz(PM)+rootCauseDonut(IA.rootCauses),'Deterministic from test-run and issue records')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Highest-occurrence issues',horizontalViz(IA.topTypes.slice(0,8)),'Ranked by occurrence, then delay impact')}${section('Automatic lessons learned',IA.lessons.slice(0,5).map(x=>`<div class="lesson-row"><span class="lesson-rank">${x.rank}</span><div><strong>${esc(x.issue)}</strong><small>${x.occurrences} occurrences · ${x.share}% · ${x.delayHours}h delay</small><p>${esc(x.lesson)}</p></div>${pill(x.priority)}</div>`).join('')||'<div class="empty">No issues in this period.</div>','Generated from recurring issue patterns')}</div>`+
 `<div class="grid section-grid" style="margin-top:14px"><div class="grid">${section('Portfolio delivery',programmeRows(vd.programmes.slice().sort((a,b)=>priorityRank[b.priority]-priorityRank[a.priority]||new Date(a.dueDate)-new Date(b.dueDate)).slice(0,8),vd),'Forecast vs requested due date')}${section('Capacity by test category',cats.map(c=>`<div class="bar-row"><div class="bar-head"><strong>${esc(c.category)}</strong><span>${c.open} open · ${c.upcomingHours}h upcoming · ${c.late} late</span></div><div class="progress"><span style="width:${Math.max(3,c.utilisation)}%"></span></div></div>`).join(''))}</div><div class="grid">${section('Top bottlenecks',bn.map((b,i)=>`<div class="list-row"><div><strong>${i+1}. ${esc(b.name)}</strong><small>${esc(b.detail)}</small></div><span class="score">${b.score}</span></div>`).join(''),'Calculated from schedule and competency data')}${section('Priority scenario comparison',scenarioCards(),'Compare project-priority strategies without changing baseline until Apply')}</div></div>`;}

function dashboardFilterBar(){const f=state.settings.dashboardFilters||{};const customers=[...new Set(state.programmes.map(p=>p.customer))].sort(),cats=[...new Set(state.methods.map(m=>m.category))].sort();return `<div class="filters"><select id="dashProgramme"><option value="">All programmes</option>${state.programmes.map(p=>`<option value="${p.id}" ${f.programme===p.id?'selected':''}>${p.id} · ${esc(p.project)}</option>`).join('')}</select><select id="dashCustomer"><option value="">All customers</option>${customers.map(x=>`<option ${f.customer===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="dashCategory"><option value="">All test categories</option>${cats.map(x=>`<option ${f.category===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="dashPriority"><option value="">All priorities</option>${['Critical','High','Normal','Low'].map(x=>`<option ${f.priority===x?'selected':''}>${x}</option>`).join('')}</select><select id="dashStatus"><option value="">All risk states</option>${['On Track','At Risk','Late','Blocked'].map(x=>`<option ${f.status===x?'selected':''}>${x}</option>`).join('')}</select><select id="dashEquipment"><option value="">All equipment</option>${state.equipment.map(e=>`<option value="${e.id}" ${f.equipment===e.id?'selected':''}>${e.id}</option>`).join('')}</select><select id="dashStaff"><option value="">All staff</option>${state.staff.map(x=>`<option value="${x.id}" ${f.staff===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div>`}
function filteredDashboardData(){const f=state.settings.dashboardFilters||{};let programs=state.programmes.filter(p=>(!f.programme||p.id===f.programme)&&(!f.customer||p.customer===f.customer)&&(!f.priority||p.priority===f.priority)&&(!f.status||p.scheduleRisk===f.status));const pids=new Set(programs.map(p=>p.id));let methods=state.methods.filter(m=>!f.category||m.category===f.category),mids=new Set(methods.map(m=>m.id));let legs=state.legs.filter(l=>pids.has(l.programmeId)&&mids.has(l.methodId)&&(!f.equipment||l.equipmentId===f.equipment)&&(!f.staff||l.staffId===f.staff));const legIds=new Set(legs.map(l=>l.id));if(f.category||f.equipment||f.staff){const usedPids=new Set(legs.map(l=>l.programmeId));programs=programs.filter(p=>usedPids.has(p.id));}const finalPids=new Set(programs.map(p=>p.id));const requirements=state.requirements.filter(r=>finalPids.has(r.programmeId));const bookings=state.bookings.filter(b=>legIds.has(b.legId)&&(!f.equipment||b.equipmentId===f.equipment)&&(!f.staff||b.staffId===f.staff));const equipment=f.equipment?state.equipment.filter(e=>e.id===f.equipment):state.equipment;const staff=f.staff?state.staff.filter(s=>s.id===f.staff):state.staff;const testRuns=(state.testRuns||[]).filter(r=>finalPids.has(r.programmeId)&&mids.has(r.methodId)&&(!f.equipment||r.equipmentId===f.equipment)&&(!f.staff||r.staffId===f.staff));const runIds=new Set(testRuns.map(r=>r.id));const issues=(state.issues||[]).filter(i=>finalPids.has(i.programmeId)&&(!i.testRunId||runIds.has(i.testRunId)));return {...state,programmes:programs,requirements,methods,legs,duts:state.duts.filter(d=>finalPids.has(d.programmeId)),bookings,equipment,staff,devTasks:state.devTasks.filter(d=>finalPids.has(d.programmeId)),specifications:(state.specifications||[]).filter(x=>finalPids.has(x.programmeId)),testRuns,issues,disruptions:(state.disruptions||[]).filter(d=>finalPids.has(d.programmeId))};}

function programmeRows(programmes,data=state){return `<div class="table-wrap"><table><thead><tr><th>Programme</th><th>Project</th><th>Priority</th><th>Due</th><th>Forecast</th><th>Risk</th><th>Progress</th></tr></thead><tbody>${programmes.map(p=>{const ls=data.legs.filter(l=>l.programmeId===p.id),done=ls.filter(l=>l.status==='Completed').length;return `<tr><td><span class="link mono" data-entity="programme" data-id="${p.id}">${p.id}</span></td><td><strong>${esc(p.project)}</strong><div class="muted small">${esc(p.product)}</div></td><td>${pill(p.priority)}</td><td>${fmtDate(p.dueDate)}</td><td>${fmtDate(p.forecastCompletion)}</td><td>${pill(p.scheduleRisk||'Unplanned')}</td><td><div class="bar-head"><span>${done}/${ls.length}</span><span>${pct(done,ls.length)}%</span></div><div class="progress"><span style="width:${pct(done,ls.length)}%"></span></div></td></tr>`}).join('')}</tbody></table></div>`}
function reqHealth(data=state){const sts=['Verified','Partially Verified','Planned','Blocked','Failed','Not Covered'];return `<div class="list">${sts.map(s=>{const n=data.requirements.filter(r=>r.status===s).length;return `<div class="bar-row"><div class="bar-head"><strong>${s}</strong><span>${n} · ${pct(n,data.requirements.length)}%</span></div><div class="progress"><span style="width:${pct(n,data.requirements.length)}%"></span></div></div>`}).join('')}</div>`}
function devRows(data=state){return `<div class="list">${data.devTasks.slice(0,6).map(d=>`<div class="list-row"><div><strong>${d.id} · ${esc(d.name)}</strong><small>${esc(data.programmes.find(p=>p.id===d.programmeId)?.project)} · ${d.estimatedEngineeringHours}h engineering · due ${fmtDate(d.dueDate)}</small></div>${pill(d.completeDate?'Complete':d.status)}</div>`).join('')}</div>`}

function renderRequirements(){const opts=[...new Set(state.requirements.map(r=>r.status))].sort();return pageHead('Requirement Flowdown','Source requirement → validation requirement → test demand → execution evidence',`<button class="btn" data-act="export-req-csv">⇩ Requirements CSV</button>`)+
 `<div class="filters"><select id="reqStatus"><option value="">All status</option>${opts.map(x=>`<option>${x}</option>`).join('')}</select><select id="reqCrit"><option value="">All criticality</option><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select><input id="reqFilter" placeholder="Filter ID, text, programme…"></div><div id="reqKpis" class="grid kpi"></div><section class="card"><div class="section-title"><h2>Requirement Traceability Matrix</h2><span class="hint">Click a requirement for end-to-end flowdown</span></div><div class="table-wrap"><table><thead><tr><th>Requirement</th><th>Source</th><th>Programme</th><th>Criticality</th><th>Verification</th><th>Test / Leg</th><th>DUT Coverage</th><th>Status</th><th>Evidence</th></tr></thead><tbody id="reqBody"></tbody></table></div></section>`;}
function renderReqTable(){const f=(document.getElementById('reqFilter')?.value||'').toLowerCase(),st=document.getElementById('reqStatus')?.value||'',cr=document.getElementById('reqCrit')?.value||'';const rows=state.requirements.filter(r=>(!st||r.status===st)&&(!cr||r.criticality===cr)&&(!f||`${r.id} ${r.sourceId} ${r.text} ${r.programmeId}`.toLowerCase().includes(f)));const covered=rows.filter(r=>r.status!=='Not Covered').length,ver=rows.filter(r=>r.status==='Verified').length,fail=rows.filter(r=>r.status==='Failed').length;document.getElementById('reqKpis').innerHTML=kpiCard('Shown',rows.length,`${covered} covered`)+kpiCard('Coverage',`${pct(covered,rows.length)}%`,'Mapped to one or more test legs')+kpiCard('Verified',`${pct(ver,rows.length)}%`,`${ver} requirements`)+kpiCard('Failed',fail,'Derived from test results')+kpiCard('Not planned',rows.filter(r=>r.status==='Not Covered').length,'No test coverage')+kpiCard('Critical outstanding',rows.filter(r=>r.criticality==='Critical'&&r.status!=='Verified').length,'Management attention');document.getElementById('reqBody').innerHTML=rows.map(r=>{const p=state.programmes.find(p=>p.id===r.programmeId),ls=state.legs.filter(l=>l.requirementIds.includes(r.id));const dutCount=new Set(ls.flatMap(l=>l.dutIds)).size,ev=state.results.filter(x=>ls.some(l=>l.id===x.legId)).length;return `<tr><td><span class="link mono" data-entity="requirement" data-id="${r.id}">${r.id}</span><div class="small muted">${esc(r.text).slice(0,80)}${r.text.length>80?'…':''}</div></td><td class="mono">${r.sourceId}</td><td>${p?.id}<div class="muted small">${esc(p?.project)}</div></td><td>${pill(r.criticality)}</td><td>${r.verificationMethod}</td><td>${ls.map(l=>`<span class="link mono" data-entity="leg" data-id="${l.id}">${l.id}</span>`).join(', ')||'—'}</td><td>${dutCount} DUTs</td><td>${pill(r.status)}</td><td>${ev?`${ev} result records`:'—'}</td></tr>`}).join('')||'<tr><td colspan="9" class="empty">No requirements match the filters.</td></tr>';wireEntities(document.getElementById('reqBody'));}


function renderSpecifications(){const specs=state.specifications||[],flagged=specs.filter(x=>(x.qualityFlags||[]).length||Number(x.qualityScore)<70),avg=Math.round(specs.reduce((a,x)=>a+(Number(x.qualityScore)||0),0)/Math.max(1,specs.length));return pageHead('Test Specifications','Upload, version and link validation/test specifications to programmes, requirements and methods',`<button class="btn primary" data-act="upload-spec">＋ Upload Test Spec</button>`)+`<div class="grid kpi">${kpiCard('Specifications',specs.length,'Browser-local documents and metadata')}${kpiCard('Released',specs.filter(x=>x.status==='Released').length,'Available for test execution')}${kpiCard('Draft / review',specs.filter(x=>x.status!=='Released').length,'Not fully released')}${kpiCard('Quality flags',flagged.length,'Ambiguity / completeness risk')}${kpiCard('Average quality',`${avg}%`,'Demo completeness score')}${kpiCard('Spec-caused issues',(state.issues||[]).filter(i=>i.rootCause==='Bad Specification').length,'Historical + current issue records')}</div><div class="filters"><select id="specProg"><option value="">All programmes</option>${state.programmes.map(p=>`<option value="${p.id}">${p.id} · ${esc(p.project)}</option>`).join('')}</select><select id="specStatus"><option value="">All status</option><option>Released</option><option>Draft</option><option>Review</option><option>Obsolete</option></select><input id="specFilter" placeholder="Filter spec, product, owner, revision…"></div><section class="card"><div class="section-title"><h2>Specification Register</h2><span class="hint">Dummy PDFs are included; uploaded files persist in IndexedDB</span></div><div class="table-wrap"><table><thead><tr><th>Specification</th><th>Programme / Product</th><th>Revision</th><th>Status</th><th>Owner</th><th>Linked coverage</th><th>Quality</th><th>Spec issues</th><th>Document</th></tr></thead><tbody id="specBody"></tbody></table></div></section>`}
function renderSpecTable(){const prog=document.getElementById('specProg')?.value||'',status=document.getElementById('specStatus')?.value||'',q=(document.getElementById('specFilter')?.value||'').toLowerCase();const rows=(state.specifications||[]).filter(sp=>(!prog||sp.programmeId===prog)&&(!status||sp.status===status)&&(!q||`${sp.id} ${sp.name} ${sp.revision} ${sp.owner} ${sp.programmeId}`.toLowerCase().includes(q)));const body=document.getElementById('specBody');if(!body)return;body.innerHTML=rows.map(sp=>{const p=state.programmes.find(x=>x.id===sp.programmeId),n=(state.issues||[]).filter(i=>i.specificationId===sp.id).length,score=Number(sp.qualityScore)||0;return`<tr><td><span class="link mono" data-entity="specification" data-id="${sp.id}">${sp.id}</span><div><strong>${esc(sp.name)}</strong></div><div class="small muted">${esc(sp.category||'Test Specification')}</div></td><td>${sp.programmeId}<div class="small muted">${esc(p?.project||'')} · ${esc(p?.product||'')}</div></td><td><strong>${esc(sp.revision)}</strong><div class="small muted">effective ${fmtDate(sp.effectiveDate)}</div></td><td>${pill(sp.status)}</td><td>${esc(sp.owner||'—')}</td><td>${(sp.linkedRequirementIds||[]).length} requirements<div class="small muted">${(sp.linkedMethodIds||[]).length} methods</div></td><td><div class="quality-score ${score<70?'bad':score<80?'warn':'good'}"><strong>${score}%</strong><div class="progress"><span style="width:${score}%"></span></div></div>${(sp.qualityFlags||[]).slice(0,1).map(x=>`<div class="small muted">${esc(x)}</div>`).join('')}</td><td>${n?`<span class="pill ${n>2?'red':'amber'}">${n} issue${n===1?'':'s'}</span>`:'—'}</td><td><button class="btn small" data-act="open-spec" data-id="${sp.id}">${sp.fileData?'Preview upload':'Open PDF'}</button></td></tr>`}).join('')||'<tr><td colspan="9"><div class="empty">No specifications match the filter.</div></td></tr>';wireEntities(body);for(const b of body.querySelectorAll('[data-act]'))b.addEventListener('click',handleAction)}
function showSpecification(id){const sp=(state.specifications||[]).find(x=>x.id===id);if(!sp)return;const p=state.programmes.find(x=>x.id===sp.programmeId),issues=(state.issues||[]).filter(i=>i.specificationId===sp.id);openModal(`<h2>${sp.id} Rev ${esc(sp.revision)} · ${esc(sp.name)}</h2><div class="detail-grid"><div class="detail"><small>Programme</small><strong>${sp.programmeId} · ${esc(p?.project||'')}</strong></div><div class="detail"><small>Status</small><strong>${esc(sp.status)}</strong></div><div class="detail"><small>Owner</small><strong>${esc(sp.owner||'—')}</strong></div><div class="detail"><small>Effective</small><strong>${fmtDate(sp.effectiveDate)}</strong></div><div class="detail"><small>Quality score</small><strong>${sp.qualityScore||'—'}%</strong></div><div class="detail"><small>Linked coverage</small><strong>${(sp.linkedRequirementIds||[]).length} req · ${(sp.linkedMethodIds||[]).length} methods</strong></div></div><div class="callout"><strong>Acceptance basis:</strong> ${esc(sp.acceptanceBasis||'—')}</div>${(sp.qualityFlags||[]).length?`<div class="callout warning" style="margin-top:10px"><strong>Specification quality flags</strong>${sp.qualityFlags.map(x=>`<div>• ${esc(x)}</div>`).join('')}</div>`:''}<h3>Linked methods</h3><div class="status-strip">${(sp.linkedMethodIds||[]).map(x=>`<span class="pill blue">${x}</span>`).join('')||'—'}</div><h3>Specification-caused issues</h3>${issues.map(i=>`<div class="list-row"><div><strong>${i.id} · ${esc(i.issueType)}</strong><small>${fmtDate(i.reportedAt)} · ${i.delayHours}h delay · ${esc(i.description)}</small></div>${pill(i.severity)}</div>`).join('')||'<div class="empty">No linked specification issues.</div>'}<div class="actions" style="margin-top:14px"><button id="specOpenDoc" class="btn primary">${sp.fileData?'Preview / Download Uploaded File':'Open Dummy Specification PDF'}</button></div>`);document.getElementById('specOpenDoc').onclick=()=>openSpecificationDocument(sp)}
function openSpecificationDocument(sp){const src=sp.fileData||sp.documentPath;if(!src)return toast('No document is attached to this specification.');if((sp.mimeType||'').includes('pdf')||String(src).startsWith('data:application/pdf'))window.open(src.startsWith('data:')?src:`./${src}`,'_blank','noopener');else download(sp.documentName||`${sp.id}-spec`,dataURLToBlob(src),sp.mimeType||'application/octet-stream')}
function dataURLToBlob(dataURL){if(!(dataURL||'').startsWith('data:'))return new Blob([dataURL||'']);const [head,body]=dataURL.split(','),mime=(head.match(/data:([^;]+)/)||[])[1]||'application/octet-stream',bin=atob(body),arr=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)arr[i]=bin.charCodeAt(i);return new Blob([arr],{type:mime})}
function uploadSpecModal(){openModal(`<h2>Upload Test Specification</h2><div class="modal-grid"><div class="field"><label>Programme</label><select id="upSpecProg">${state.programmes.map(p=>`<option value="${p.id}">${p.id} · ${esc(p.project)} · ${esc(p.product)}</option>`).join('')}</select></div><div class="field"><label>Specification ID</label><input id="upSpecId" value="SPEC-${String((state.specifications||[]).length+1).padStart(3,'0')}"></div><div class="field"><label>Name</label><input id="upSpecName" value="Validation Test Specification"></div><div class="field"><label>Revision</label><input id="upSpecRev" value="R1"></div><div class="field"><label>Category</label><select id="upSpecCat"><option>Product Validation</option><option>Environmental</option><option>Electrical</option><option>Mechanical</option><option>Reliability</option><option>EMC</option><option>Test Method</option></select></div><div class="field"><label>Status</label><select id="upSpecStatus"><option>Released</option><option>Draft</option><option>Review</option></select></div><div class="field"><label>Owner</label><select id="upSpecOwner">${state.staff.map(x=>`<option>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Effective date</label><input id="upSpecDate" type="date" value="${DEMO_NOW.toISOString().slice(0,10)}"></div><div class="field"><label>Primary test method (optional)</label><select id="upSpecMethod"><option value="">Programme methods automatically linked</option>${state.methods.map(m=>`<option value="${m.id}">${m.id} · ${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label>Specification file</label><input id="upSpecFile" type="file" accept=".pdf,.doc,.docx,.txt,.csv,image/*"></div></div><div class="field"><label>Acceptance basis / notes</label><textarea id="upSpecBasis">Released limits, sample population, sequence and acceptance criteria.</textarea></div><div class="callout">The file is stored browser-locally with the specification metadata. This static prototype does not upload it to a server.</div><div class="actions" style="margin-top:14px"><button id="saveSpec" class="btn primary">Save Specification</button></div>`);document.getElementById('saveSpec').onclick=async()=>{const file=document.getElementById('upSpecFile').files[0];if(!file)return toast('Select a specification file to upload.');if(file.size>8*1024*1024)return toast('For this prototype, keep uploaded specifications below 8 MB.');const id=document.getElementById('upSpecId').value.trim();if(!id)return toast('Specification ID is required.');if(state.specifications.some(x=>x.id===id))return toast('Specification ID already exists.');const pid=document.getElementById('upSpecProg').value,method=document.getElementById('upSpecMethod').value,fileData=await fileToDataURL(file),reqIds=state.requirements.filter(r=>r.programmeId===pid).map(r=>r.id),methodIds=[...new Set([...state.legs.filter(l=>l.programmeId===pid).map(l=>l.methodId),...(method?[method]:[])])];const sp={id,programmeId:pid,name:document.getElementById('upSpecName').value.trim()||file.name,revision:document.getElementById('upSpecRev').value.trim()||'R1',category:document.getElementById('upSpecCat').value,status:document.getElementById('upSpecStatus').value,owner:document.getElementById('upSpecOwner').value,effectiveDate:new Date(document.getElementById('upSpecDate').value+'T08:00:00Z').toISOString(),uploadedAt:new Date().toISOString(),source:'User upload',acceptanceBasis:document.getElementById('upSpecBasis').value.trim(),description:'Browser-local uploaded test specification.',linkedMethodIds:methodIds,linkedRequirementIds:reqIds,documentName:file.name,documentPath:null,mimeType:file.type||'application/octet-stream',fileData,qualityScore:document.getElementById('upSpecStatus').value==='Released'?85:70,qualityFlags:document.getElementById('upSpecStatus').value==='Released'?[]:['Document is not yet Released']};state.specifications.push(sp);state.documents.push({id:`DOC-${id}`,type:'Test Specification',entityId:id,name:sp.name,path:`embedded:${id}`});state.audit.push(audit('Test specification uploaded',id,'',`${file.name} · ${sp.revision}`));await persist();closeModal();render();toast(`${id} uploaded and linked to ${reqIds.length} requirements.`)}}

function renderProgrammes(){return pageHead('Validation Programmes','Prioritise programmes and inspect flowdown, DUT populations, schedule risk and completion',`<button class="btn primary" data-act="replan">↻ Recalculate Laboratory Plan</button>`)+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Programme</th><th>Customer / Product</th><th>Owner</th><th>Priority</th><th>Business score</th><th>Due</th><th>Forecast</th><th>Risk</th><th>Progress</th></tr></thead><tbody>${state.programmes.map(p=>{const ls=state.legs.filter(l=>l.programmeId===p.id),done=ls.filter(l=>l.status==='Completed').length;return `<tr><td><span class="link mono" data-entity="programme" data-id="${p.id}">${p.id}</span><div><strong>${esc(p.project)}</strong></div><div class="small muted">${esc(p.storyline)}</div></td><td>${esc(p.customer)}<div class="small muted">${esc(p.product)} · ${p.productRevision}</div></td><td>${esc(p.owner)}</td><td><select class="priority-change" data-id="${p.id}">${['Critical','High','Normal','Low'].map(x=>`<option ${x===p.priority?'selected':''}>${x}</option>`).join('')}</select></td><td>${p.businessPriority}</td><td>${fmtDate(p.dueDate)}</td><td>${fmtDate(p.forecastCompletion)}</td><td>${pill(p.scheduleRisk||p.status)}</td><td>${done}/${ls.length}<div class="progress"><span style="width:${pct(done,ls.length)}%"></span></div></td></tr>`}).join('')}</tbody></table></div></section>`}

function renderPlanning(){const m=computePlanningMetrics(state),active=(state.disruptions||[]).filter(d=>d.status==='Active');return pageHead('Test Planning','Automatic resource-constrained plan that can be refreshed immediately when samples, tests, people or equipment change',`<button class="btn" data-act="report-issue">＋ Log Delay / Issue</button><button class="btn" data-act="scenario">◈ What-if</button><button class="btn primary" data-act="update-plan">↻ Update Plan Now</button>`)+
 `<div class="planning-summary"><span class="metric-chip"><b>${m.planned}</b> scheduled</span><span class="metric-chip"><b>${m.unscheduled}</b> unscheduled</span><span class="metric-chip"><b>${m.late}</b> late bookings</span><span class="metric-chip"><b>${m.atRisk}</b> programmes at risk</span><span class="metric-chip ${state.settings.planDirty?'attention':''}"><b>${active.length}</b> active operational events ${state.settings.planDirty?'· plan refresh needed':''}</span>${state.settings.scenario?`<span class="metric-chip">Scenario: <b>${esc(state.settings.scenario.label||state.settings.scenario.type)}</b> <button class="btn small" data-act="reset-scenario">Reset</button></span>`:''}</div>`+
 `<div class="grid section-grid equal">${section('Live planning inputs',activeDisruptionRows(),'Sample delays, test issues and equipment events are hard planning inputs')}${section('Priority strategy scenarios',`<div class="field" style="padding:0 14px"><label>Focus-project scenario</label><select id="scenarioFocus">${state.programmes.map(p=>`<option value="${p.id}" ${state.settings.scenarioFocusProgramme===p.id?'selected':''}>${p.id} · ${esc(p.project)}</option>`).join('')}</select></div>${scenarioCards()}`,'Compare alternative project prioritisation before applying')}</div>`+
 `<div style="margin-top:14px">${section('Equipment timeline · next 14 days',planningTimeline(),'Click a booking to inspect or manually lock/move it')}</div>`+
 `<div style="margin-top:14px">${section('Staff planning view',planningStaffRows(),'Qualified attended bookings in the next 14 days')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Unscheduled / blocked demand',unscheduledRows())}${section('Last replanning impact',planMoveRows())}</div>`;}
function activeDisruptionRows(){const rows=(state.disruptions||[]).filter(d=>d.status==='Active').sort((a,b)=>new Date(a.effectiveUntil)-new Date(b.effectiveUntil));if(!rows.length)return'<div class="empty">No active operational events. The plan is using normal sample and resource availability.</div>';return `<div class="table-wrap"><table><thead><tr><th>Event</th><th>Programme / Leg</th><th>Constraint until</th><th>Impact</th><th>Action</th></tr></thead><tbody>${rows.map(d=>`<tr><td><strong>${d.id}</strong><div class="small muted">${esc(d.type.replaceAll('_',' '))}</div><div>${esc(d.reason)}</div></td><td>${d.programmeId||'—'}<div class="small muted">${d.legId||d.equipmentId||'programme-level'}</div></td><td>${fmtDate(d.effectiveUntil,true)}</td><td>${Math.round((d.impactHours||0)/24*10)/10} days</td><td><button class="btn small" data-act="resolve-disruption" data-id="${d.id}">Resolve</button></td></tr>`).join('')}</tbody></table></div>`}

function planningTimeline(){const days=Array.from({length:14},(_,i)=>new Date(DEMO_NOW.getTime()+i*86400000));const eqRows=state.equipment.filter(e=>state.bookings.some(b=>b.equipmentId===e.id)||state.maintenance.some(m=>m.equipmentId===e.id)).slice(0,18);const header=`<div class="gantt-head"><div>Equipment</div>${days.map(d=>`<div>${d.toLocaleDateString(undefined,{weekday:'short',day:'numeric'})}</div>`).join('')}</div>`;const rows=eqRows.map(eq=>{const blocks=[];for(const b of state.bookings.filter(x=>x.equipmentId===eq.id)){const a=(new Date(b.start)-DEMO_NOW)/86400000,z=(new Date(b.end)-new Date(b.start))/86400000;if(a<14&&a+z>0)blocks.push(`<div class="booking ${b.lateHours>0?'late':''} ${b.locked?'locked':''}" data-booking="${b.id}" style="left:calc(180px + ${Math.max(0,a)} * ((100% - 180px)/14));width:calc(${Math.max(.08,Math.min(14-a,z))} * ((100% - 180px)/14))" title="${b.id}">${b.legId} · ${b.programmeId}</div>`)}for(const x of state.maintenance.filter(m=>m.equipmentId===eq.id)){const a=(new Date(x.start)-DEMO_NOW)/86400000,z=(new Date(x.end)-new Date(x.start))/86400000;if(a<14&&a+z>0)blocks.push(`<div class="booking maint" style="left:calc(180px + ${Math.max(0,a)} * ((100% - 180px)/14));width:calc(${Math.max(.08,Math.min(14-a,z))} * ((100% - 180px)/14))">${esc(x.type)}</div>`)}return `<div class="gantt-row"><div class="gantt-label"><span class="link" data-entity="equipment" data-id="${eq.id}">${eq.id}</span>&nbsp;${esc(eq.name)}</div>${days.map(()=>'<div class="gantt-cell"></div>').join('')}${blocks.join('')}</div>`}).join('');return `<div class="timeline-legend" style="padding:9px 14px"><span><i class="legend-box"></i> planned</span><span><i class="legend-box late"></i> late</span><span><i class="legend-box maint"></i> maintenance / outage</span><span>▣ outline = locked</span></div><div class="gantt-shell"><div class="gantt">${header}${rows}</div></div>`}
function planningStaffRows(){const end=new Date(DEMO_NOW.getTime()+14*86400000),rows=state.staff.map(s=>{const bs=state.bookings.filter(b=>b.staffId===s.id&&new Date(b.start)<end&&new Date(b.staffEnd||b.end)>DEMO_NOW).sort((a,b)=>new Date(a.start)-new Date(b.start));const hours=bs.reduce((sum,b)=>sum+(new Date(b.staffEnd||b.end)-new Date(b.start))/3600000,0);return {s,bs,hours}}).filter(x=>x.bs.length).sort((a,b)=>b.hours-a.hours);return `<div class="table-wrap"><table><thead><tr><th>Staff</th><th>Role</th><th>Booked attended hours</th><th>Upcoming allocations</th></tr></thead><tbody>${rows.map(x=>`<tr><td><span class="link" data-entity="staff" data-id="${x.s.id}">${esc(x.s.name)}</span></td><td>${esc(x.s.role)}</td><td>${x.hours.toFixed(1)}h</td><td>${x.bs.map(b=>`${b.legId} · ${fmtDate(b.start,true)}`).join('<br>')}</td></tr>`).join('')}</tbody></table></div>`}
function unscheduledRows(){const ls=state.legs.filter(l=>l.status!=='Completed'&&!l.plannedStart);return `<div class="list">${ls.slice(0,12).map(l=>`<div class="list-row"><div><strong><span class="link mono" data-entity="leg" data-id="${l.id}">${l.id}</span> · ${esc(l.name)}</strong><small>${l.programmeId} · due ${fmtDate(l.dueDate)} · ${esc(l.blockingReason||'Awaiting feasible slot')}</small></div>${pill(l.status)}</div>`).join('')||'<div class="empty">All active test demand is scheduled.</div>'}</div>`}
function planMoveRows(){const moved=lastPlanDiagnostics?.moved||[];return `<div class="list">${moved.slice(0,10).map(x=>`<div class="list-row"><div><strong>${x.legId}</strong><small>${fmtDate(x.oldStart,true)} → ${fmtDate(x.newStart,true)} · ${x.oldEquipment||'—'} → ${x.newEquipment||'—'}</small></div>${pill('Rescheduled')}</div>`).join('')||'<div class="empty">No schedule moves recorded in the latest recalculation.</div>'}</div>`}

function renderExecution(){const legs=state.legs.slice().sort((a,b)=>{const order={"In Progress":0,"At Risk":1,"Planned":2,"Blocked":3,"Completed":4,"Draft":5};return (order[a.status]??9)-(order[b.status]??9)});return pageHead('Test Execution','Lifecycle control, readiness checks, results and deterministic acceptance evaluation')+
 `<div class="grid kpi">${kpiCard('In progress',legs.filter(l=>l.status==='In Progress').length,'Active executions')}${kpiCard('Ready / planned',legs.filter(l=>['Ready','Planned'].includes(l.status)).length,'Awaiting start')}${kpiCard('Blocked',legs.filter(l=>l.blockingReason).length,'Constraint or prerequisite')}${kpiCard('Completed',legs.filter(l=>l.status==='Completed').length,'Evidence captured')}${kpiCard('Failed DUTs',state.duts.filter(d=>d.status==='Failed').length,'Derived from results')}${kpiCard('Awaiting review',legs.filter(l=>l.status==='Awaiting Review').length,'Quality review queue')}</div>`+
 `<section class="card"><div class="table-wrap"><table><thead><tr><th>Leg</th><th>Programme</th><th>Method</th><th>DUTs</th><th>Planned</th><th>Resources</th><th>Status</th><th>Blocking / Evidence</th><th>Action</th></tr></thead><tbody>${legs.map(l=>{const m=state.methods.find(x=>x.id===l.methodId),res=state.results.filter(r=>r.legId===l.id);return `<tr><td><span class="link mono" data-entity="leg" data-id="${l.id}">${l.id}</span><div class="muted small">${esc(l.name)}</div></td><td>${l.programmeId}</td><td>${m?.id} Rev ${m?.revision}</td><td>${l.dutIds.length}</td><td>${fmtDate(l.plannedStart,true)}<div class="muted small">→ ${fmtDate(l.plannedEnd,true)}</div></td><td>${l.equipmentId||'—'}<div class="muted small">${state.staff.find(s=>s.id===l.staffId)?.name||'—'}</div></td><td>${pill(l.status)}</td><td><span class="small">${esc(l.blockingReason||`${res.length} result records`)}</span></td><td>${l.status==='In Progress'?`<button class="btn small primary" data-act="record-result" data-id="${l.id}">Results</button>`:`<button class="btn small" data-act="readiness" data-id="${l.id}">Check</button>`}</td></tr>`}).join('')}</tbody></table></div></section>`}

function renderDUTs(){return pageHead('DUTs & Specimens','Genealogy, programme allocation, failed/removed units and complete test journey')+`<div class="filters"><select id="dutProg"><option value="">All programmes</option>${state.programmes.map(p=>`<option value="${p.id}">${p.id} · ${esc(p.project)}</option>`).join('')}</select><select id="dutStatus"><option value="">All status</option><option>Available</option><option>Failed</option><option>Removed</option></select><input id="dutFilter" placeholder="Serial number or DUT ID"></div><section class="card"><div class="table-wrap"><table><thead><tr><th>DUT</th><th>Serial</th><th>Product</th><th>Programme</th><th>Group</th><th>Status</th><th>Legs assigned</th><th>Results</th></tr></thead><tbody id="dutBody"></tbody></table></div></section>`}
function renderDutTable(){const pr=document.getElementById('dutProg')?.value||'',st=document.getElementById('dutStatus')?.value||'',f=(document.getElementById('dutFilter')?.value||'').toLowerCase();const rows=state.duts.filter(d=>(!pr||d.programmeId===pr)&&(!st||d.status===st)&&(!f||`${d.id} ${d.serialNumber}`.toLowerCase().includes(f)));document.getElementById('dutBody').innerHTML=rows.map(d=>{const ls=state.legs.filter(l=>l.dutIds.includes(d.id)),rs=state.results.filter(r=>r.dutId===d.id);return `<tr><td><span class="link mono" data-entity="dut" data-id="${d.id}">${d.id}</span></td><td>${d.serialNumber}</td><td>${esc(d.product)}</td><td>${d.programmeId}</td><td>${d.group}</td><td>${pill(d.status)}</td><td>${ls.length}</td><td>${rs.length} · ${rs.some(r=>r.status==='FAIL')?pill('FAIL'):rs.length?pill('PASS'):'—'}</td></tr>`}).join('');wireEntities(document.getElementById('dutBody'));}

function renderLibrary(){const methods=state.methods;return pageHead('Test Library','Reusable released test methods with resource requirements, standard durations and performance analytics',`<button class="btn primary" data-act="request-new-test">＋ Request New Test</button>`)+`<div class="grid kpi">${kpiCard('Active methods',methods.filter(m=>m.active).length,'Across '+new Set(methods.map(m=>m.category)).size+' categories')}${kpiCard('Standard execution',state.legs.filter(l=>!l.developmentTaskId).length,'Legs using released methods')}${kpiCard('Development-linked',state.legs.filter(l=>l.developmentTaskId).length,'Validation legs gated by method development')}${kpiCard('Avg actual variance',`${Math.round(methods.reduce((s,m)=>s+(m.avgActualFactor-1),0)/methods.length*100)}%`,'Actual vs library standard')}${kpiCard('Unattended methods',methods.filter(m=>m.unattended).length,'Equipment continues without full-time staffing')}${kpiCard('Obsolete',methods.filter(m=>!m.active).length,'Excluded from new plans')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Method</th><th>Category</th><th>Rev</th><th>Standard duration</th><th>Required resource</th><th>Skill</th><th>DUT capacity</th><th>Staffing</th><th>Uses</th><th>Actual vs std</th></tr></thead><tbody>${methods.map(m=>`<tr><td><span class="link mono" data-entity="method" data-id="${m.id}">${m.id}</span><div><strong>${esc(m.name)}</strong></div></td><td>${m.category}</td><td>${m.revision}</td><td>${m.setupHours+m.executionHours+m.teardownHours+m.analysisHours}h<div class="muted small">setup ${m.setupHours} · run ${m.executionHours} · teardown ${m.teardownHours} · analysis ${m.analysisHours}</div></td><td>${m.equipmentType}</td><td>${m.requiredSkills.join(', ')}</td><td>${m.dutCapacity}</td><td>${m.unattended?'Unattended capable':'Continuous / attended'}</td><td>${m.useCount}</td><td>${Math.round(m.avgActualFactor*100)}%</td></tr>`).join('')}</tbody></table></div></section>`}

function renderEquipment(){const u=resourceUtilisation(state),map=Object.fromEntries(u.equipment.map(x=>[x.id,x]));return pageHead('Equipment Register','Capability, utilisation, calibration, maintenance and planning availability',`<button class="btn" data-act="export-equipment-csv">⇩ Equipment CSV</button>`)+`<div class="grid kpi">${kpiCard('Assets',state.equipment.length,'Registered laboratory equipment')}${kpiCard('Available',state.equipment.filter(e=>e.status==='Available').length,'Current asset status')}${kpiCard('Maintenance',state.equipment.filter(e=>e.status==='Maintenance').length,'Unavailable by status')}${kpiCard('Breakdown',state.equipment.filter(e=>e.status==='Breakdown').length,'Corrective maintenance')}${kpiCard('Calibration risk',state.equipment.filter(e=>['red','amber'].includes(calibrationStatus(e,state).tone)).length,'Expired or due ≤60d')}${kpiCard('Portfolio utilisation',`${u.equipmentAvg}%`,'Next 4 weeks')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Asset</th><th>Type / Capability</th><th>Manufacturer</th><th>Location</th><th>Status</th><th>Capacity</th><th>Utilisation</th><th>Calibration</th><th>Maintenance</th></tr></thead><tbody>${state.equipment.map(e=>{const c=calibrationStatus(e,state),ut=map[e.id]?.pct||0;return `<tr><td><span class="link mono" data-entity="equipment" data-id="${e.id}">${e.id}</span><div class="muted small">${e.assetNumber} · ${e.serialNumber}</div></td><td><strong>${esc(e.name)}</strong><div class="muted small">${esc(e.capability)}</div></td><td>${e.manufacturer}<div class="muted small">${e.model}</div></td><td>${e.location}</td><td>${pill(e.status)}</td><td>${e.capacity}</td><td><div class="bar-head"><span>${ut}%</span></div><div class="heat"><span style="width:${ut}%"></span></div></td><td><span class="pill ${c.tone}">${c.label}</span><div class="muted small">${fmtDate(e.calibrationDue)}</div></td><td>${fmtDate(e.maintenanceDate)}</td></tr>`}).join('')}</tbody></table></div></section>`}

function renderCalibration(){const current=state.equipment.filter(e=>e.calibrationRequired).map(e=>{const s=calibrationStatus(e,state),c=s.calibration,next=nextScheduledCalibration(state,e.id);return{e,c,next,s}}).sort((a,b)=>(a.s.days??999)-(b.s.days??999));const affected=state.bookings.filter(b=>{const e=state.equipment.find(x=>x.id===b.equipmentId);if(!e?.calibrationRequired)return false;const c=calibrationAt(state,e.id,b.start,{allowScheduled:true});return !c||new Date(c.dueDate)<new Date(b.end)}).length;return pageHead('Calibration Management','Validity, warning horizons, certificates and planning impact',`<button class="btn" data-act="add-calibration">＋ Add Calibration</button><button class="btn" data-act="export-cal-csv">⇩ CSV</button>`)+`<div class="grid kpi">${kpiCard('Valid',current.filter(x=>x.s.tone==='green').length,'Beyond 60-day warning')}${kpiCard('Due ≤60d',current.filter(x=>x.s.tone==='amber').length,'Amber warning')}${kpiCard('Expired / ≤7d',current.filter(x=>x.s.tone==='red').length,'Planning blocker / urgent')}${kpiCard('Calibration records',state.calibrations.length,'Current, historical + scheduled')}${kpiCard('Future tests affected',affected,'Effective calibration checked at planned use')}${kpiCard('Warning thresholds',state.settings.calibrationWarningDays.join(' / ')+'d','Configurable in Administration')}</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Equipment</th><th>Current calibration</th><th>Date</th><th>Due</th><th>Status</th><th>Next planned</th><th>Provider</th><th>Certificate</th><th>As found / left</th></tr></thead><tbody>${current.map(x=>`<tr><td><span class="link mono" data-entity="equipment" data-id="${x.e.id}">${x.e.id}</span><div>${esc(x.e.name)}</div></td><td class="mono">${x.c?.id||'—'}</td><td>${fmtDate(x.c?.calibrationDate)}</td><td>${fmtDate(x.c?.dueDate)}</td><td><span class="pill ${x.s.tone}">${x.s.label}</span></td><td>${x.next?`<span class="pill blue">Scheduled</span><div class="muted small">${fmtDate(x.next.calibrationDate,true)} · ${esc(x.next.id)}</div>`:'—'}</td><td>${esc(x.c?.provider||'—')}</td><td>${x.c?`<a class="link" href="${esc(x.c.certificatePath)}" target="_blank" rel="noopener">${esc(x.c.certificateNumber)}</a>`:'—'}</td><td>${esc(x.c?.asFound||'—')} / ${esc(x.c?.asLeft||'—')}</td></tr>`).join('')}</tbody></table></div></section>`}

function renderPeople(){const u=resourceUtilisation(state),um=Object.fromEntries(u.staff.map(x=>[x.id,x])),risks=skillsRisks(state);return pageHead('People & Skills','Competency, authorisation, availability, workload and single-point qualification risks')+`<div class="grid kpi">${kpiCard('Staff',state.staff.length,'Technicians, engineers, specialists, manager')}${kpiCard('Staff utilisation',`${u.staffAvg}%`,'Attended planning load')}${kpiCard('Single-point skills',risks.filter(r=>r.count===1).length,'Only one independent operator')}${kpiCard('Qualification gaps',risks.filter(r=>r.count===0).length,'No independent coverage')}${kpiCard('Methods covered',`${pct(state.methods.length-risks.filter(r=>r.count===0).length,state.methods.length)}%`,'At least one independent qualification')}${kpiCard('People unavailable',state.staff.filter(s=>s.availability.some(a=>new Date(a.end)>DEMO_NOW)).length,'Future leave / training blocks')}</div><div class="grid section-grid"><section class="card"><div class="section-title"><h2>Staff workload</h2></div><div class="table-wrap"><table><thead><tr><th>Person</th><th>Role / Team</th><th>Skills</th><th>Qualifications</th><th>Availability</th><th>Workload</th></tr></thead><tbody>${state.staff.map(s=>{const ut=um[s.id]?.pct||0;return `<tr><td><span class="link" data-entity="staff" data-id="${s.id}">${esc(s.name)}</span><div class="mono small muted">${s.id}</div></td><td>${esc(s.role)}<div class="muted small">${esc(s.team)}</div></td><td>${s.skills.join(', ')}</td><td>${s.qualifications.length}<div class="muted small">${s.proficiency}</div></td><td>${s.availability.map(a=>`${fmtDate(a.start)}–${fmtDate(a.end)} ${a.reason}`).join('<br>')||'Available'}</td><td>${ut}%<div class="heat"><span style="width:${ut}%"></span></div></td></tr>`}).join('')}</tbody></table></div></section>${section('Single-point competency risks',risks.slice(0,15).map(r=>`<div class="list-row"><div><strong>${r.methodId} · ${esc(r.name)}</strong><small>${r.count?esc(r.people):'No independent qualified person'}</small></div><span class="pill ${r.count===0?'red':'amber'}">${r.count} qualified</span></div>`).join('')||'<div class="empty">No coverage risks.</div>','Independent / Reviewer / Expert levels')}</div>`}

function renderAnalytics(){const p=periodRange(),PM=periodMetrics(state,p.start,p.end),TR=periodTrend(state,p.start,p.end),IA=issueAnalytics(state,p.start,p.end);const cats={};for(const r of PM.runs){const m=state.methods.find(x=>x.id===r.methodId),c=m?.category||'Other';cats[c]=cats[c]||{name:c,count:0,actual:0,standard:0,fail:0};cats[c].count++;cats[c].actual+=Number(r.actualHours)||0;cats[c].standard+=Number(r.standardHours)||0;if(r.outcome==='FAIL')cats[c].fail++;}const catRows=Object.values(cats).sort((a,b)=>b.count-a.count);const meth={};for(const r of PM.runs){const m=state.methods.find(x=>x.id===r.methodId);meth[r.methodId]=meth[r.methodId]||{id:r.methodId,name:m?.name||r.methodId,count:0,actual:0,standard:0};const x=meth[r.methodId];x.count++;x.actual+=Number(r.actualHours)||0;x.standard+=Number(r.standardHours)||0;}const methodRows=Object.values(meth).map(x=>({...x,variance:Math.round((x.actual-x.standard)/Math.max(1,x.standard)*100)})).sort((a,b)=>Math.abs(b.variance)-Math.abs(a.variance)).slice(0,12);return pageHead('Reports / Analytics','Period-selectable laboratory performance, issue Pareto, lessons learned, utilisation and planned-vs-actual insight',`<button class="btn" data-act="export-plan-csv">⇩ Test Plan CSV</button><button class="btn" data-act="export-kpi-csv">⇩ KPI CSV</button>`)+periodControls()+
 `<div class="grid kpi visual-kpis">${kpiCard('Completed',PM.completed,periodLabel())}${kpiCard('On-time',`${PM.onTimePct}%`,'Actual end ≤ planned end')}${kpiCard('Pass rate',`${PM.passRate}%`,`${PM.failed} fail · ${PM.rework} rework`)}${kpiCard('Avg turnaround',`${PM.avgTurnaround}h`, `median ${PM.medianTurnaround}h`)}${kpiCard('Actual vs standard',`${PM.durationVariancePct>=0?'+':''}${PM.durationVariancePct}%`,`${PM.actualHours}h actual · ${PM.standardHours}h standard`)}${kpiCard('Issue delay',`${PM.issueDelayHours}h`,`${PM.issues} issue records`)}</div>`+
 `<div class="grid section-grid equal">${section('Throughput & issue trend',trendViz(TR),`${TR.mode} buckets · selected KPI period`)}${section('Outcome mix & issue root causes',outcomeViz(PM)+rootCauseDonut(IA.rootCauses),'Spec vs execution vs sample/equipment causes')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Issue Pareto — highest occurrence',horizontalViz(IA.topTypes.slice(0,10)),'Occurrence first; delay hours shown alongside')}${section('Execution vs bad specification',`<div class="cause-compare"><div><strong>Test execution</strong><b>${IA.testExecution}</b><span>${Math.round(IA.testExecution/Math.max(1,IA.total)*100)}% of issues</span><div class="viz-track"><i style="width:${IA.testExecution/Math.max(1,IA.total)*100}%"></i></div></div><div><strong>Bad / ambiguous specifications</strong><b>${IA.badSpecification}</b><span>${Math.round(IA.badSpecification/Math.max(1,IA.total)*100)}% of issues</span><div class="viz-track spec"><i style="width:${IA.badSpecification/Math.max(1,IA.total)*100}%"></i></div></div></div>${horizontalViz(IA.rootCauses.slice(0,7))}`,'Root cause is stored per issue and aggregated automatically')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Automatic lessons learned',IA.lessons.map(x=>`<div class="lesson-row"><span class="lesson-rank">${x.rank}</span><div><strong>${esc(x.issue)}</strong><small>${x.occurrences} occurrences · ${x.share}% of period issues · ${x.delayHours}h delay</small><p>${esc(x.lesson)}</p></div>${pill(x.priority)}</div>`).join('')||'<div class="empty">No issue history in the selected period.</div>','Ranked by recurrence and delay impact')}${section('Category throughput',horizontalViz(catRows.map(x=>({name:x.name,count:x.count,delayHours:Math.max(0,Math.round((x.actual-x.standard)*10)/10)})).slice(0,12)),'Tests completed; variance hours shown as context')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('Equipment utilisation',horizontalViz(PM.equipment.slice().sort((a,b)=>b.pct-a.pct).slice(0,12),'pct','%'),'Actual runs + future bookings inside selected period')}${section('Staff utilisation',horizontalViz(PM.staff.slice().sort((a,b)=>b.pct-a.pct).slice(0,12),'pct','%'),'Attended workload versus available working hours')}</div>`+
 `<div style="margin-top:14px">${section('Methods whose actual duration differs most from library standard',`<div class="table-wrap"><table><thead><tr><th>Method</th><th>Runs</th><th>Standard hours</th><th>Actual hours</th><th>Variance</th><th>Recommendation</th></tr></thead><tbody>${methodRows.map(x=>`<tr><td><strong>${x.id}</strong><div class="small muted">${esc(x.name)}</div></td><td>${x.count}</td><td>${Math.round(x.standard*10)/10}</td><td>${Math.round(x.actual*10)/10}</td><td><span class="pill ${Math.abs(x.variance)>=15?'amber':'green'}">${x.variance>=0?'+':''}${x.variance}%</span></td><td>${x.variance>15?'Review library duration / recurrent delay cause':x.variance<-15?'Consider reducing standard duration after sufficient evidence':'Standard duration remains representative'}</td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">No completed runs in this period.</div></td></tr>'}</tbody></table></div>`,'Planned-vs-actual feedback loop into the Test Library')}</div>`;}

function renderAdmin(){const d=runDiagnostics(state);return pageHead('Administration / Demo','Persistence, demo controls, scenarios, audit history and deterministic system verification')+`<div class="grid section-grid equal"><section class="card pad"><h2 style="margin-top:0">Demo & Data</h2><div class="detail-grid"><div class="detail"><small>Version</small><strong>LabOS Prototype v${APP_VERSION}</strong></div><div class="detail"><small>Persistence</small><strong>IndexedDB + fallback</strong></div><div class="detail"><small>Demo actor</small><strong>${esc(state.settings.actor)}</strong></div></div><div class="actions"><button class="btn" data-act="export-json">⇩ Export Data</button><button class="btn" data-act="import-json">⇧ Import Data</button><button class="btn danger" data-act="reset-demo">↺ Reset Demo Data</button></div><div class="field"><label>Demo actor</label><input id="actorInput" value="${esc(state.settings.actor)}"></div><button class="btn small" data-act="save-actor">Save actor</button><p class="small muted">Prototype audit history is browser-local and is not a validated electronic-signature or production audit system.</p></section>${section('System Data Integrity',`<div class="callout ${d.overall==='PASS'?'':'danger'}"><strong>${d.overall}</strong> · ${d.pass}/${d.checks.length} automated checks passing.</div><div class="list">${d.checks.map(c=>`<div class="checkline"><span class="${c.ok?'diag-pass':'diag-fail'}">${c.ok?'PASS':'FAIL'}</span><strong>${esc(c.name)}</strong><span class="small muted">${esc(c.detail)}</span></div>`).join('')}</div><div style="padding:12px"><button class="btn primary" data-act="verify">✓ Run System Verification</button></div>`,'Verification uses current canonical browser data')}</div>`+
 `<div class="grid section-grid equal" style="margin-top:14px">${section('What-if scenario',scenarioPanel())}${section('Calibration warning thresholds',`<div class="card pad" style="border:0;box-shadow:none"><div class="field"><label>Warning days (comma separated)</label><input id="calWarn" value="${state.settings.calibrationWarningDays.join(', ')}"></div><button class="btn small" data-act="save-warnings">Save thresholds</button><p class="small muted">Current visual bands use urgent ≤7d, warning ≤60d. Thresholds are retained for future policy expansion.</p></div>`)}</div>`+
 section('Audit History',`<div class="audit list">${state.audit.slice().reverse().slice(0,40).map(a=>`<div class="list-row"><span>${fmtDate(a.timestamp,true)}</span><strong>${esc(a.actor)}</strong><div><b>${esc(a.action)}</b> · ${esc(a.entity)}<small>${esc(a.previousValue)} ${a.previousValue||a.newValue?'→':''} ${esc(a.newValue)}</small></div></div>`).join('')}</div>`,'Latest 40 session/demo events')}

function reportIssueModal(){const activeLegs=state.legs.filter(l=>!['Completed','Cancelled','Failed'].includes(l.status));openModal(`<h2>Log Delay / Test Issue</h2><div class="modal-grid"><div class="field"><label>Event type</label><select id="issType"><option value="sample_delay">Sample / DUT delay</option><option value="test_issue">Test execution issue</option><option value="equipment_issue">Equipment outage / interruption</option><option value="spec_issue">Bad / ambiguous specification</option><option value="resource_issue">Staff / qualification issue</option></select></div><div class="field"><label>Programme</label><select id="issProg">${state.programmes.map(p=>`<option value="${p.id}">${p.id} · ${esc(p.project)}</option>`).join('')}</select></div><div class="field"><label>Affected test leg</label><select id="issLeg"><option value="">Programme-level</option>${activeLegs.map(l=>`<option value="${l.id}" data-prog="${l.programmeId}">${l.id} · ${l.programmeId} · ${esc(l.name)}</option>`).join('')}</select></div><div class="field"><label>Equipment (if applicable)</label><select id="issEq"><option value="">None / not equipment-specific</option>${state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="field"><label>Specification (if applicable)</label><select id="issSpec"><option value="">None</option>${state.specifications.map(sp=>`<option value="${sp.id}">${sp.id} Rev ${esc(sp.revision)} · ${esc(sp.name)}</option>`).join('')}</select></div><div class="field"><label>Severity</label><select id="issSeverity"><option>Low</option><option selected>Medium</option><option>High</option><option>Critical</option></select></div><div class="field"><label>Constraint / recovery until</label><input id="issUntil" type="datetime-local" value="${dayISO(3,12).slice(0,16)}"></div><div class="field"><label>Estimated delay impact (hours)</label><input id="issHours" type="number" min="0" step="1" value="24"></div></div><div class="field"><label>Issue description</label><textarea id="issDesc">Sample / test condition changed; planner must account for the new availability constraint.</textarea></div><div class="field"><label>Issue subtype</label><input id="issSubtype" value="Sample arrival delay"></div><div class="callout"><strong>Planning behaviour:</strong> sample delays, test issues, resource issues and equipment interruptions become active planning constraints. Specification issues are recorded for quality/lessons analytics and can be linked to a specific spec.</div><div class="actions" style="margin-top:14px"><button id="saveIssue" class="btn primary">Save Issue</button><button id="saveIssueReplan" class="btn">Save & Update Plan</button></div>`);const sync=()=>{const t=document.getElementById('issType').value,sub=document.getElementById('issSubtype'),desc=document.getElementById('issDesc');const map={sample_delay:['Sample arrival delay','Customer sample/DUT availability changed.'],test_issue:['Fixture / connection problem','Test execution issue requires recovery or repeat work.'],equipment_issue:['Equipment interruption','Equipment is unavailable until recovery.'],spec_issue:['Specification ambiguity','Specification ambiguity or missing acceptance criterion identified.'],resource_issue:['Qualification / staffing gap','Required competent resource is unavailable.']};sub.value=map[t][0];desc.value=map[t][1]};document.getElementById('issType').onchange=sync;const prog=document.getElementById('issProg'),legSel=document.getElementById('issLeg'),specSel=document.getElementById('issSpec');prog.onchange=()=>{for(const o of [...legSel.options])if(o.value)o.hidden=o.dataset.prog!==prog.value;legSel.value='';for(const o of [...specSel.options])if(o.value)o.hidden=state.specifications.find(x=>x.id===o.value)?.programmeId!==prog.value;specSel.value=''};prog.onchange();const save=async(doReplan)=>{const type=document.getElementById('issType').value,pid=prog.value,legId=legSel.value||null,eqId=document.getElementById('issEq').value||null,specId=document.getElementById('issSpec').value||null,severity=document.getElementById('issSeverity').value,untilRaw=document.getElementById('issUntil').value,hours=Math.max(0,Number(document.getElementById('issHours').value)||0),description=document.getElementById('issDesc').value.trim(),issueType=document.getElementById('issSubtype').value.trim()||'Operational issue';if(!description)return toast('Describe the issue.');if(type==='equipment_issue'&&!eqId)return toast('Select the affected equipment for an equipment outage.');if(type!=='spec_issue'&&!untilRaw)return toast('Set the recovery / constraint end time.');const untilDate=untilRaw?new Date(untilRaw):null;if(untilDate&&Number.isNaN(untilDate.getTime()))return toast('Enter a valid recovery time.');const until=untilDate?untilDate.toISOString():null;const rootCause=type==='spec_issue'?'Bad Specification':type==='sample_delay'?'Sample / DUT':type==='equipment_issue'?'Equipment / Facility':type==='resource_issue'?'Planning / Resource':'Test Execution';const lesson=rootCause==='Bad Specification'?'Add a specification completeness/ambiguity gate before test release':rootCause==='Test Execution'?'Standardise pre-test setup checks and capture recurrent execution failure modes':rootCause==='Sample / DUT'?'Make confirmed sample-ready date a hard planning input':'Expose resource interruptions immediately and maintain contingency capacity';const iid=`ISS-${String((state.issues||[]).length+1).padStart(3,'0')}`,issue={id:iid,reportedAt:new Date().toISOString(),programmeId:pid,legId,testRunId:null,specificationId:specId,issueType,rootCause,severity,delayHours:hours,status:'Open',description,lesson,correctiveAction:lesson,owner:state.settings.actor};state.issues.push(issue);let dsp=null;if(type!=='spec_issue'){const dtype=type==='resource_issue'?'test_issue':type;dsp={id:`DSP-${String((state.disruptions||[]).length+1).padStart(3,'0')}`,type:dtype,status:'Active',programmeId:pid,legId:legId,equipmentId:type==='equipment_issue'?eqId:null,reportedAt:new Date().toISOString(),effectiveUntil:until,reason:description,impactHours:hours,sourceIssueId:iid};state.disruptions.push(dsp);state.settings.planDirty=true}if(specId&&rootCause==='Bad Specification'){const sp=state.specifications.find(x=>x.id===specId);if(sp){sp.qualityScore=Math.max(0,(Number(sp.qualityScore)||80)-5);sp.qualityFlags=[...new Set([...(sp.qualityFlags||[]),issueType])]}}state.audit.push(audit('Operational issue logged',iid,'',`${rootCause} · ${hours}h`));if(doReplan){const r=scheduleAll(state);state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;}await persist();closeModal();render();toast(doReplan?`${iid} saved; laboratory plan updated.`:`${iid} saved. Tap “Update Plan Now” to replan.`)};document.getElementById('saveIssue').onclick=()=>save(false);document.getElementById('saveIssueReplan').onclick=()=>save(true)}
async function resolveDisruption(id){const d=(state.disruptions||[]).find(x=>x.id===id);if(!d)return;d.status='Resolved';d.resolvedAt=new Date().toISOString();const i=(state.issues||[]).find(x=>x.id===d.sourceIssueId);if(i)i.status='Closed';state.settings.planDirty=true;state.audit.push(audit('Planning disruption resolved',id,'Active','Resolved'));await persist();render();toast(`${id} resolved. Update the plan to release the constraint.`)}
async function applyPriorityScenario(strategy){const sc=priorityMaps().find(x=>x.id===strategy);if(!sc||!sc.map)return;const scenario={type:'priority_mix',priorityMap:sc.map,label:sc.name};state.settings.scenario=scenario;state.audit.push(audit('Priority scenario applied','Planning','',sc.name));const r=scheduleAll(state,{scenario});state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;await persist();render();toast(`${sc.name} applied; ${r.diagnostics.moved.length} bookings moved.`)}

function scenarioPanel(){return `<div class="card pad" style="border:0;box-shadow:none"><div class="field"><label>Scenario</label><select id="scenarioType"><option value="equipment_unavailable">Equipment unavailable for 7 days</option><option value="staff_unavailable">Staff unavailable next week</option><option value="add_equipment">Add temporary thermal chamber</option></select></div><div class="field" id="scenarioTargetWrap"><label>Target</label><select id="scenarioTarget">${state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}</select></div><div class="actions"><button class="btn primary" data-act="apply-scenario">Apply & Replan</button>${state.settings.scenario?'<button class="btn" data-act="reset-scenario">Reset Scenario</button>':''}</div>${state.settings.scenario?`<div class="callout warning" style="margin-top:12px"><strong>Active:</strong> ${esc(state.settings.scenario.label||state.settings.scenario.type)}</div>`:''}</div>`}

function wireRoute(){wireEntities(main);for(const b of main.querySelectorAll('[data-act]'))b.addEventListener('click',handleAction);for(const b of main.querySelectorAll('[data-booking]'))b.addEventListener('click',()=>showBooking(b.dataset.booking));if(route==='dashboard'){for(const x of ['dashProgramme','dashCustomer','dashCategory','dashPriority','dashStatus','dashEquipment','dashStaff']){const el=document.getElementById(x);if(el)el.addEventListener('change',async()=>{state.settings.dashboardFilters={programme:document.getElementById('dashProgramme').value,customer:document.getElementById('dashCustomer').value,category:document.getElementById('dashCategory').value,priority:document.getElementById('dashPriority').value,status:document.getElementById('dashStatus').value,equipment:document.getElementById('dashEquipment').value,staff:document.getElementById('dashStaff').value};await persist();render();});}wirePeriodControls()}if(route==='analytics')wirePeriodControls();if(route==='requirements'){for(const x of ['reqStatus','reqCrit','reqFilter'])document.getElementById(x).addEventListener('input',renderReqTable);renderReqTable()}if(route==='specifications'){for(const x of ['specProg','specStatus','specFilter'])document.getElementById(x)?.addEventListener('input',renderSpecTable);renderSpecTable()}if(route==='duts'){for(const x of ['dutProg','dutStatus','dutFilter'])document.getElementById(x).addEventListener('input',renderDutTable);renderDutTable()}if(route==='programmes'){for(const s of main.querySelectorAll('.priority-change'))s.addEventListener('change',()=>changePriority(s.dataset.id,s.value))}if(route==='planning'){const f=document.getElementById('scenarioFocus');if(f)f.onchange=async()=>{state.settings.scenarioFocusProgramme=f.value;await persist();render()}}if(route==='admin'){const t=document.getElementById('scenarioType');if(t)t.onchange=updateScenarioTargets;updateScenarioTargets();}}

function wireEntities(root){for(const el of root.querySelectorAll('[data-entity]'))el.addEventListener('click',e=>{e.preventDefault();showEntity(el.dataset.entity,el.dataset.id)})}

async function handleAction(e){const b=e.currentTarget,a=b.dataset.act,id=b.dataset.id;if(a==='replan'||a==='update-plan')return replan();if(a==='scenario')return go('admin');if(a==='reset-scenario')return resetScenario();if(a==='readiness')return showReadiness(id);if(a==='export-json')return exportJSON();if(a==='import-json')return document.getElementById('importFile').click();if(a==='reset-demo')return resetDemo();if(a==='verify')return verifyUI();if(a==='export-req-csv')return exportCSV('requirements');if(a==='export-equipment-csv')return exportCSV('equipment');if(a==='export-cal-csv')return exportCSV('calibrations');if(a==='export-plan-csv')return exportCSV('plan');if(a==='export-kpi-csv')return exportCSV('kpis');if(a==='save-actor'){const v=document.getElementById('actorInput').value.trim()||'Demo Lab Manager';state.audit.push(audit('Demo actor changed','Settings',state.settings.actor,v));state.settings.actor=v;await persist();render();return}if(a==='save-warnings'){const v=document.getElementById('calWarn').value.split(',').map(x=>parseInt(x.trim())).filter(x=>Number.isFinite(x)&&x>0).sort((a,b)=>b-a);if(!v.length)return toast('Enter at least one positive warning threshold.');state.settings.calibrationWarningDays=v;state.audit.push(audit('Calibration warning thresholds changed','Settings','',v.join(',')));await persist();render();return}if(a==='apply-scenario')return applyScenario();if(a==='apply-priority-scenario')return applyPriorityScenario(b.dataset.strategy);if(a==='add-calibration')return addCalibrationModal();if(a==='request-new-test')return requestNewTestModal();if(a==='record-result')return recordResultModal(id);if(a==='report-issue')return reportIssueModal();if(a==='resolve-disruption')return resolveDisruption(id);if(a==='upload-spec')return uploadSpecModal();if(a==='open-spec'){const sp=state.specifications.find(x=>x.id===id);return sp?openSpecificationDocument(sp):null;}}

async function replan(){const r=scheduleAll(state);state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;recomputeRequirementStatuses(state);await persist();render();toast(`Plan updated from current delays/issues: ${r.diagnostics.moved.length} moved, ${r.diagnostics.unscheduled.length} unscheduled.`)}
async function changePriority(id,val){state=applyPriority(state,id,val);const r=scheduleAll(state);state=r.data;state.settings.planDirty=false;lastPlanDiagnostics=r.diagnostics;await persist();render();toast(`${id} set to ${val}; ${r.diagnostics.moved.length} bookings moved.`)}
function updateScenarioTargets(){const t=document.getElementById('scenarioType'),sel=document.getElementById('scenarioTarget');if(!t||!sel)return;if(t.value==='staff_unavailable')sel.innerHTML=state.staff.map(s=>`<option value="${s.id}">${s.id} · ${esc(s.name)}</option>`).join('');else if(t.value==='add_equipment')sel.innerHTML=[...new Set(state.equipment.map(e=>e.type))].sort().map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');else sel.innerHTML=state.equipment.map(e=>`<option value="${e.id}">${e.id} · ${esc(e.name)}</option>`).join('')}
async function applyScenario(){const type=document.getElementById('scenarioType').value,target=document.getElementById('scenarioTarget').value;let sc;if(type==='equipment_unavailable')sc={type,equipmentId:target,start:dayISO(0,8),end:dayISO(7,17),label:`${target} unavailable for 7 days`};else if(type==='staff_unavailable')sc={type,staffId:target,start:dayISO(3,8),end:dayISO(10,17),label:`${state.staff.find(s=>s.id===target)?.name} unavailable next week`};else sc={type,equipmentType:target,label:`Add temporary ${target}`};state.settings.scenario=sc;state.audit.push(audit('Scenario applied','Planning','',sc.label));const r=scheduleAll(state,{scenario:sc});state=r.data;lastPlanDiagnostics=r.diagnostics;await persist();render();toast(`Scenario applied; ${r.diagnostics.moved.length} bookings moved.`)}
async function resetScenario(){state.settings.scenario=null;state.audit.push(audit('Scenario reset','Planning','active','baseline'));const r=scheduleAll(state,{scenario:null});state=r.data;lastPlanDiagnostics=r.diagnostics;await persist();render();toast('Scenario reset and baseline schedule recalculated.');}

function showEntity(type,id){if(type==='requirement')return showRequirement(id);if(type==='specification')return showSpecification(id);if(type==='programme')return showProgramme(id);if(type==='leg')return showLeg(id);if(type==='dut')return showDut(id);if(type==='equipment')return showEquipmentDetail(id);if(type==='method')return showMethod(id);if(type==='staff')return showStaff(id)}
function showRequirement(id){const r=state.requirements.find(x=>x.id===id);if(!r)return;const p=state.programmes.find(x=>x.id===r.programmeId),ls=state.legs.filter(l=>l.requirementIds.includes(r.id)),results=state.results.filter(x=>ls.some(l=>l.id===x.legId));openModal(`<h2>${r.id} · Requirement Traceability</h2><div class="callout"><strong>${esc(r.text)}</strong></div><div class="trace"><div class="trace-step"><small>Source Requirement</small><strong>${r.sourceId}</strong></div><div class="trace-step"><small>Validation Requirement</small><strong>${r.id}</strong></div><div class="trace-step"><small>Verification</small><strong>${r.verificationMethod}</strong></div><div class="trace-step"><small>Test Programme</small><strong>${p?.id} · ${esc(p?.project)}</strong></div><div class="trace-step"><small>Test Legs</small><strong>${ls.map(l=>l.id).join(', ')||'Not covered'}</strong></div><div class="trace-step"><small>Test Method</small><strong>${[...new Set(ls.map(l=>l.methodId))].join(', ')||'—'}</strong></div><div class="trace-step"><small>DUTs</small><strong>${new Set(ls.flatMap(l=>l.dutIds)).size} assigned</strong></div><div class="trace-step"><small>Results / Evidence</small><strong>${results.length} results</strong></div><div class="trace-step"><small>Verification Status</small><strong>${r.status}</strong></div></div><div class="detail-grid"><div class="detail"><small>Criticality</small><strong>${r.criticality}</strong></div><div class="detail"><small>Owner</small><strong>${esc(r.owner)}</strong></div><div class="detail"><small>Coverage</small><strong>${ls.length} test legs</strong></div></div>${results.length?`<div class="table-wrap"><table><thead><tr><th>Result</th><th>DUT</th><th>Parameter</th><th>Value</th><th>Status</th><th>Evidence</th></tr></thead><tbody>${results.slice(0,25).map(x=>`<tr><td>${x.id}</td><td>${x.dutId}</td><td>${x.parameter}</td><td>${x.value} ${x.unit}</td><td>${pill(x.status)}</td><td>${x.evidenceId}</td></tr>`).join('')}</tbody></table></div>`:''}`)}
function showProgramme(id){const p=state.programmes.find(x=>x.id===id),ls=state.legs.filter(l=>l.programmeId===id),req=state.requirements.filter(r=>r.programmeId===id),duts=state.duts.filter(d=>d.programmeId===id),spec=state.specifications?.find(s=>s.programmeId===id);if(!p)return;openModal(`<h2>${p.id} · ${esc(p.project)}</h2><div class="detail-grid"><div class="detail"><small>Customer</small><strong>${esc(p.customer)}</strong></div><div class="detail"><small>Product</small><strong>${esc(p.product)} ${p.productRevision}</strong></div><div class="detail"><small>Priority / Risk</small><strong>${p.priority} · ${p.scheduleRisk}</strong></div><div class="detail"><small>Due</small><strong>${fmtDate(p.dueDate)}</strong></div><div class="detail"><small>Forecast</small><strong>${fmtDate(p.forecastCompletion)}</strong></div><div class="detail"><small>Owner</small><strong>${esc(p.owner)}</strong></div><div class="detail"><small>Specification</small><strong>${spec?`${spec.id} Rev ${spec.revision}`:'—'}</strong></div></div><div class="callout warning"><strong>Demo storyline:</strong> ${esc(p.storyline)}</div><h3>Test programme legs</h3><div class="tree">${ls.map(l=>`<div class="tree-item"><span>${l.sequence}</span><strong>${l.id}</strong><span>${esc(l.name)}</span>${pill(l.status)}</div>`).join('')}</div><h3>Coverage</h3><p class="small">${req.length} requirements · ${duts.length} DUTs · ${req.filter(r=>r.status==='Verified').length} verified · ${req.filter(r=>r.status==='Failed').length} failed.</p>`)}
function showLeg(id){const l=state.legs.find(x=>x.id===id);if(!l)return;const m=state.methods.find(x=>x.id===l.methodId),p=state.programmes.find(x=>x.id===l.programmeId),s=state.staff.find(x=>x.id===l.staffId);openModal(`<h2>${l.id} · ${esc(l.name)}</h2><div class="detail-grid"><div class="detail"><small>Programme</small><strong>${p?.id} · ${esc(p?.project)}</strong></div><div class="detail"><small>Method</small><strong>${m?.id} Rev ${m?.revision}</strong></div><div class="detail"><small>Status</small><strong>${l.status}</strong></div><div class="detail"><small>Planned</small><strong>${fmtDate(l.plannedStart,true)} → ${fmtDate(l.plannedEnd,true)}</strong></div><div class="detail"><small>Equipment</small><strong>${l.equipmentId||'—'}</strong></div><div class="detail"><small>Operator</small><strong>${esc(s?.name||'—')}</strong></div></div><h3>Planning explanation</h3><div class="callout ${l.blockingReason?'warning':''}">${(l.planExplanation?.length?l.planExplanation:[l.blockingReason||'Scheduled without exceptional constraints.']).map(x=>`<div>• ${esc(x)}</div>`).join('')}</div><h3>DUT population</h3><p class="small">${l.dutIds.join(', ')}</p><h3>Requirements covered</h3><p class="small">${l.requirementIds.join(', ')}</p>`)}
function showDut(id){const d=state.duts.find(x=>x.id===id);if(!d)return;const ls=state.legs.filter(l=>l.dutIds.includes(d.id)).sort((a,b)=>a.sequence-b.sequence);openModal(`<h2>${d.id} · DUT Journey</h2><div class="detail-grid"><div class="detail"><small>Serial</small><strong>${d.serialNumber}</strong></div><div class="detail"><small>Programme</small><strong>${d.programmeId}</strong></div><div class="detail"><small>Status</small><strong>${d.status}</strong></div></div><div class="tree">${ls.map((l,i)=>{const r=state.results.find(x=>x.legId===l.id&&x.dutId===d.id);return `<div class="tree-item"><span>${i+1}</span><strong>${l.id}</strong><span>${esc(l.name)}</span>${r?pill(r.status):pill(l.status)}</div>`}).join('')}</div><p class="small muted">Genealogy is derived from canonical leg-to-DUT allocation; failed units remain visible in historical leg membership.</p>`)}
