function showMethod(id){const m=state.methods.find(x=>x.id===id);if(!m)return;openModal(`<h2>${m.id} Rev ${m.revision} · ${esc(m.name)}</h2><div class="callout">${esc(m.description)}</div><div class="detail-grid"><div class="detail"><small>Category</small><strong>${m.category}</strong></div><div class="detail"><small>Total standard time</small><strong>${m.setupHours+m.executionHours+m.teardownHours+m.analysisHours}h</strong></div><div class="detail"><small>Equipment</small><strong>${m.equipmentType}</strong></div><div class="detail"><small>Skill</small><strong>${m.requiredSkills.join(', ')}</strong></div><div class="detail"><small>DUT capacity</small><strong>${m.dutCapacity}</strong></div><div class="detail"><small>Operation</small><strong>${m.unattended?'Unattended capable':'Continuous staffing'}</strong></div></div><h3>Acceptance</h3><p>${esc(m.acceptance)}</p>`)}
